SET NAMES utf8mb4;
ALTER TABLE clientes ADD COLUMN telefono VARCHAR(30) NULL AFTER nombre_completo, ADD COLUMN correo VARCHAR(160) NULL AFTER telefono, ADD COLUMN direccion VARCHAR(255) NULL AFTER correo, ADD COLUMN distrito VARCHAR(100) NULL AFTER direccion, ADD COLUMN provincia VARCHAR(100) NULL AFTER distrito, ADD COLUMN departamento VARCHAR(100) NULL AFTER provincia;
ALTER TABLE operaciones ADD COLUMN producto VARCHAR(100) NULL AFTER cartera, ADD COLUMN origen_entidad VARCHAR(100) NULL AFTER producto, ADD COLUMN periodo_archivo CHAR(8) NULL AFTER estado, ADD COLUMN fecha_carga_origen DATE NULL AFTER periodo_archivo, ADD COLUMN activa_en_asignacion TINYINT(1) NOT NULL DEFAULT 1 AFTER fecha_carga_origen, ADD COLUMN sync_batch VARCHAR(64) NULL AFTER activa_en_asignacion;
ALTER TABLE acuerdos ADD COLUMN telefono_documento VARCHAR(30) NULL AFTER fecha_acuerdo, ADD COLUMN correo_documento VARCHAR(160) NULL AFTER telefono_documento;
CREATE TABLE sincronizaciones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asignacion VARCHAR(100) NOT NULL,periodo_archivo CHAR(8) NOT NULL,batch_id VARCHAR(64) NOT NULL,filas_recibidas INT UNSIGNED NOT NULL DEFAULT 0,estado ENUM('INICIADA','COMPLETA','ERROR') NOT NULL DEFAULT 'INICIADA',detalle VARCHAR(255) NULL,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,UNIQUE KEY uq_sync_batch(batch_id),INDEX idx_sync_asignacion_periodo(asignacion,periodo_archivo)) ENGINE=InnoDB;
CREATE TABLE documentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,acuerdo_id BIGINT UNSIGNED NOT NULL,tipo ENUM('ACUERDO_PAGO','CESION_DERECHOS') NOT NULL,estado ENUM('PENDIENTE','GENERANDO','DISPONIBLE','ERROR') NOT NULL DEFAULT 'PENDIENTE',nombre_descarga VARCHAR(255) NOT NULL,storage_key VARCHAR(255) NULL,solicitado_por BIGINT UNSIGNED NOT NULL,generado_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_documento_acuerdo_tipo(acuerdo_id,tipo),CONSTRAINT fk_documento_acuerdo FOREIGN KEY(acuerdo_id) REFERENCES acuerdos(id) ON DELETE CASCADE,CONSTRAINT fk_documento_usuario FOREIGN KEY(solicitado_por) REFERENCES usuarios(id)) ENGINE=InnoDB;
